To make things simpler for individual projections, since they all will be using RavenDB for
now, I created a simple base abstract class called RavenDbProjecion. It accepts the session
factory for its constructor and contains a helpful method to execute updates on read model
documents and that's why the class is a generic class, so we will use the read model class
type as a generic parameter:
using System;
using System.Linq.Expressions;
using System.Threading.Tasks;
using Marketplace.Framework;
using Raven.Client.Documents;
using Raven.Client.Documents.Linq;
using Raven.Client.Documents.Session;
namespace Marketplace.Infrastructure
{
public abstract class RavenDbProjection<T> : IProjection
{
protected RavenDbProjection(
Func<IAsyncDocumentSession> getSession
)
=> GetSession = getSession;
protected Func<IAsyncDocumentSession> GetSession { get; }
public abstract Task Project(object @event);
protected Task Create(Func<Task<T>> model)
=> UsingSession(
async session =>
await session.StoreAsync(await model())
);
protected Task UpdateOne(Guid id, Action<T> update)
=> UsingSession(
session =>
UpdateItem(session, id, update)
);
protected Task UpdateWhere(
Expression<Func<T, bool>> where,
Action<T> update
) => UsingSession(
session =>
UpdateMultipleItems(
session, where, update
)
